use agmp_native_protocol::JavaRuntimeInfo;use anyhow::{bail,Context,Result};use flate2::read::GzDecoder;use reqwest::blocking::Client;use serde_json::Value;use sha2::{Digest,Sha256};use std::{fs,io::{Read,Write},path::{Path,PathBuf},process::Command,time::Duration};use tar::Archive;use uuid::Uuid;
pub fn ensure(root:&Path,major:u32)->Result<JavaRuntimeInfo>{fs::create_dir_all(root.join("java"))?;if let Some(info)=scan(root,major){return Ok(info)}let os=match std::env::consts::OS{"windows"=>"windows","linux"=>"linux","macos"=>"mac",other=>bail!("unsupported OS {other}")};let arch=match std::env::consts::ARCH{"x86_64"=>"x64","aarch64"=>"aarch64",other=>bail!("unsupported arch {other}")};let api=format!("https://api.adoptium.net/v3/assets/latest/{major}/hotspot?architecture={arch}&image_type=jre&os={os}&vendor=eclipse");let client=Client::builder().timeout(Duration::from_secs(300)).user_agent("agmp-native/0.4.0").build()?;let assets:Value=client.get(&api).send()?.error_for_status()?.json()?;let first=assets.as_array().and_then(|a|a.first()).ok_or_else(||anyhow::anyhow!("Adoptium returned no JRE"))?;let pkg=&first["binary"]["package"];let url=pkg["link"].as_str().ok_or_else(||anyhow::anyhow!("missing Adoptium link"))?;let expected=pkg["checksum"].as_str().ok_or_else(||anyhow::anyhow!("missing Adoptium sha256"))?.to_ascii_lowercase();let name=pkg["name"].as_str().unwrap_or("temurin");let version=first["version"]["semver"].as_str().unwrap_or("latest");let target=root.join("java").join(format!("{major}-{version}"));let tmp=root.join(format!(".java-{}",Uuid::new_v4()));fs::create_dir_all(&tmp)?;let archive=tmp.join(name);let mut resp=client.get(url).send()?.error_for_status()?;let mut f=fs::File::create(&archive)?;let mut hash=Sha256::new();let mut buf=[0u8;65536];loop{let n=resp.read(&mut buf)?;if n==0{break}hash.update(&buf[..n]);f.write_all(&buf[..n])?}let actual=hex::encode(hash.finalize());if actual!=expected{let _=fs::remove_dir_all(&tmp);bail!("Adoptium SHA-256 mismatch")};let extract=tmp.join("extract");fs::create_dir_all(&extract)?;if name.ends_with(".zip"){let mut zip=zip::ZipArchive::new(fs::File::open(&archive)?)?;zip.extract(&extract)?}else if name.ends_with(".tar.gz"){let gz=GzDecoder::new(fs::File::open(&archive)?);Archive::new(gz).unpack(&extract)?}else{bail!("unsupported Java archive")};let home=single_child_or_self(&extract)?;if target.exists(){fs::remove_dir_all(&target)?}fs::rename(&home,&target).or_else(|_|copy_dir(&home,&target))?;let _=fs::remove_dir_all(&tmp);verify_java(&target,major,"AGMP managed")}
fn scan(root:&Path,major:u32)->Option<JavaRuntimeInfo>{let dir=root.join("java");for e in fs::read_dir(dir).ok()?.flatten(){if let Ok(info)=verify_java(&e.path(),major,"AGMP managed"){return Some(info)}}None}
fn verify_java(home:&Path,major:u32,source:&str)->Result<JavaRuntimeInfo>{let exe=home.join("bin").join(if cfg!(windows){"java.exe"}else{"java"});let o=Command::new(&exe).arg("-version").output().context("managed java -version")?;let t=format!("{}{}",String::from_utf8_lossy(&o.stderr),String::from_utf8_lossy(&o.stdout));let version=t.split('"').nth(1).unwrap_or_default().to_string();let parsed=if version.starts_with("1."){version.split('.').nth(1).and_then(|x|x.parse().ok()).unwrap_or(0)}else{version.split(['.','-','+']).next().and_then(|x|x.parse().ok()).unwrap_or(0)};if !o.status.success()||parsed!=major{bail!("managed Java verification failed: expected {major}, got {parsed}")};Ok(JavaRuntimeInfo{available:true,executable:exe.to_string_lossy().into_owned(),major:parsed,version,source:source.into(),error:String::new()})}
fn single_child_or_self(root:&Path)->Result<PathBuf>{let dirs=fs::read_dir(root)?.filter_map(|e|e.ok()).map(|e|e.path()).filter(|p|p.is_dir()).collect::<Vec<_>>();Ok(if dirs.len()==1{dirs[0].clone()}else{root.to_path_buf()})}
fn copy_dir(src:&Path,dst:&Path)->Result<()>{fs::create_dir_all(dst)?;for e in fs::read_dir(src)?{let e=e?;let to=dst.join(e.file_name());if e.file_type()?.is_dir(){copy_dir(&e.path(),&to)?}else{fs::copy(e.path(),to)?;}}Ok(())}
